const opciones = {
  'Nativo (Kotlin + Swift)': { equipoWeb: 1, mismaUI: 1, apisDia1: 5, equipoKotlin: 4, unSoloCodigo: 1, costoInicial: 1 },
  'Híbrido (WebView)':       { equipoWeb: 5, mismaUI: 5, apisDia1: 2, equipoKotlin: 1, unSoloCodigo: 5, costoInicial: 5 },
  'React Native + Expo':     { equipoWeb: 4, mismaUI: 4, apisDia1: 3, equipoKotlin: 1, unSoloCodigo: 4, costoInicial: 4 },
  'Flutter':                 { equipoWeb: 2, mismaUI: 5, apisDia1: 3, equipoKotlin: 1, unSoloCodigo: 5, costoInicial: 4 },
  'Kotlin Multiplatform':    { equipoWeb: 1, mismaUI: 3, apisDia1: 4, equipoKotlin: 5, unSoloCodigo: 3, costoInicial: 3 },
};
const perfiles = {
  'Startup con equipo web, sale en 3 meses': { equipoWeb: 5, mismaUI: 3, apisDia1: 1, equipoKotlin: 0, unSoloCodigo: 4, costoInicial: 5 },
  'Banco con equipo Android ya armado':      { equipoWeb: 0, mismaUI: 1, apisDia1: 4, equipoKotlin: 5, unSoloCodigo: 2, costoInicial: 1 },
  'Juego o app con UI propia y muy cuidada': { equipoWeb: 0, mismaUI: 5, apisDia1: 4, equipoKotlin: 0, unSoloCodigo: 3, costoInicial: 2 },
};
for (const [perfil, pesos] of Object.entries(perfiles)) {
  const puntajes = Object.entries(opciones).map(([nombre, notas]) => {
    let total = 0;
    for (const criterio in pesos) total += pesos[criterio] * notas[criterio];
    return [nombre, total];
  }).sort((a, b) => b[1] - a[1]);
  console.log(perfil);
  puntajes.slice(0, 2).forEach(([n, t]) => console.log('  ' + t + '  ' + n));
}
